"""Tensor-parallel linear layers implemented with ``torch.distributed``."""

import torch
from torch import nn
from torch.nn import functional as F



def _validate_partition(size: int, world_size: int, name: str) -> int:
    if size % world_size != 0:
        raise ValueError(
            f"{name} ({size}) must be divisible by the distributed world size "
            f"({world_size})"
        )
    return size // world_size


def _validate_master_weight(
    master_weight: torch.Tensor, in_features: int, out_features: int
) -> None:
    if master_weight.ndim != 2:
        raise ValueError("master_weight must be a 2-dimensional tensor")
    if tuple(master_weight.shape) != (out_features, in_features):
        raise ValueError(
            "master_weight must have shape "
            f"({out_features}, {in_features}), got {tuple(master_weight.shape)}"
        )


class _AllGatherLastDim(torch.autograd.Function):
    @staticmethod
    def forward(ctx, tensor: torch.Tensor) -> torch.Tensor:
        world_size = torch.distributed.get_world_size()
        rank = torch.distributed.get_rank()
        ctx.world_size = world_size
        ctx.rank = rank

        if world_size == 1:
            return tensor

        gathered = [torch.empty_like(tensor) for _ in range(world_size)]
        torch.distributed.all_gather(gathered, tensor)
        return torch.cat(gathered, dim=-1)

    @staticmethod
    def backward(ctx, grad_output: torch.Tensor):
        if ctx.world_size == 1:
            return grad_output

        local_grad = grad_output.chunk(ctx.world_size, dim=-1)[ctx.rank].contiguous()
        # Every rank receives the concatenated output, so gradients for a local
        # shard must include contributions from every rank's output.
        torch.distributed.all_reduce(local_grad)
        return local_grad


class _AllReduceSum(torch.autograd.Function):
    @staticmethod
    def forward(ctx, tensor: torch.Tensor) -> torch.Tensor:
        world_size = torch.distributed.get_world_size()
        ctx.world_size = world_size

        if world_size == 1:
            return tensor

        reduced = tensor.clone()
        torch.distributed.all_reduce(reduced)
        return reduced

    @staticmethod
    def backward(ctx, grad_output: torch.Tensor):
        if ctx.world_size == 1:
            return grad_output

        grad_input = grad_output.contiguous()
        torch.distributed.all_reduce(grad_input)
        return grad_input


class ColumnParallelLinear(nn.Module):
    """Linear layer sharded over its output features.

    Each rank owns a contiguous range of rows of the full linear weight.  Its
    output and bias are correspondingly sharded, and the output shards are
    gathered along the final dimension.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()

        world_size = torch.distributed.get_world_size()
        rank = torch.distributed.get_rank()
        _validate_master_weight(master_weight, in_features, out_features)
        local_out_features = _validate_partition(
            out_features, world_size, "out_features"
        )

        local_weight = master_weight.chunk(world_size, dim=0)[rank].detach().clone()
        self.weight = nn.Parameter(local_weight)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    local_out_features,
                    device=master_weight.device,
                    dtype=master_weight.dtype,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, input: torch.Tensor) -> torch.Tensor:
        local_output = F.linear(input, self.weight, self.bias)
        return _AllGatherLastDim.apply(local_output)


class RowParallelLinear(nn.Module):
    """Linear layer sharded over its input features.

    The input to ``forward`` must already contain this rank's input-feature
    shard.  Partial outputs are reduced across ranks, after which the full
    bias (replicated on every rank) is added.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()

        world_size = torch.distributed.get_world_size()
        rank = torch.distributed.get_rank()
        _validate_master_weight(master_weight, in_features, out_features)
        _validate_partition(in_features, world_size, "in_features")

        local_weight = master_weight.chunk(world_size, dim=1)[rank].detach().clone()
        self.weight = nn.Parameter(local_weight)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    out_features,
                    device=master_weight.device,
                    dtype=master_weight.dtype,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, input: torch.Tensor) -> torch.Tensor:
        partial_output = F.linear(input, self.weight, bias=None)
        output = _AllReduceSum.apply(partial_output)
        if self.bias is not None:
            output = output + self.bias
        return output

